from dataclasses import dataclass

@dataclass
class FailureMode:
    mode: str            # e.g. downstream timeout / duplicate delivery
    detector: str        # SLI that proves it
    mitigation: str      # bounded action, not "retry forever"
    budget: str          # explicit price you will pay

# Mini-FMEA for checkout -> payments. Each row must compile to config.
FMEA = [
    FailureMode("payments slow (p99 >800ms)", "deadline_exceeded_total", "deadline 800ms + hedge after 600ms, bulkhead 20 conns", "max 1 hedge, shed after bulkhead full"),
    FailureMode("payments timeout then retry", "retry_budget_burn", "idempotency-Key + exactly-once store, retry x2 exp+jitter", "retry budget 10% of QPS, else fail-fast"),
    FailureMode("queue redelivery duplicate", "consumer_duplicate_total", "idempotent handler + dedup table with atomic insert", "dedup TTL 7d; spill to DLQ after 5 attempts"),
]

def should_retry(attempt: int, budget_remaining: float) -> bool:
    # Trade-off made explicit: masking transients vs amplifying overload.
    if attempt >= 2:
        return False
    if budget_remaining <= 0:
        return False  # fail fast to protect downstream
    return True
